import { papers, type Paper } from './content';
import { additionalPapers, studyContent } from './studies';
import type { HandbookEntry, HandbookSection, SourceRef } from './handbookTypes';

export const foundationSources: SourceRef[] = [
  {id:'study-guide',title:'Supplied LDW Study & Revision Guide',basis:'supplied-summary',locator:'ldw_study_guide.docx; conceptual questions, mathematics and oral examination'},
  {id:'paper-map',title:'Supplied LDW Paper Map',basis:'supplied-summary',locator:'ldw_paper_map.docx; numbered paper entries 1 to 19'},
  {id:'quick-reference',title:'Supplied updated paper quick reference',basis:'supplied-summary',locator:'LDW_Paper_Quick_Reference_Updated.docx; paper-by-paper summaries'},
];
const sectionId = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const location: Record<string,string> = {
  hidden:'RGB pixels',rosteals:'Clean autoencoder latent', 'stable-signature':'VAE decoder weights',wouaf:'Generator weights',aqualora:'Denoiser weights',sleepermark:'Denoiser weights',zodiac:'Optimised cover-image latent','semantic-forgery':'No embedding: forgery attack',
  'latent-watermark':'Learned latent representation', 'gaussian-shannon':'Initial noise',gaussmarker:'Initial noise: spatial and Fourier',lawa:'VAE decoder feature maps','tree-rings':'Initial noise: Fourier',robin:'Intermediate diffusion state',ringid:'Initial noise: Fourier','object-watermark':'Object-conditioned latent',serum:'Initial noise',seal:'Semantic content and latent key',sfwmark:'Initial noise: Fourier','tag-wm':'Semantic content and integrity signal','gaussian-shading':'Initial noise',t2smark:'Initial noise: tails','gaussian-shading-plus-plus':'Initial noise','prc-watermark':'Initial noise',
};
const related: Record<string,string[]> = {
 hidden:['rosteals','stable-signature','push-it-away'],rosteals:['hidden','zodiac','latent-watermark'],'stable-signature':['aqualora','wouaf','tree-rings'],wouaf:['aqualora','ringid'],aqualora:['wouaf','sleepermark','stable-signature'],sleepermark:['aqualora','stable-signature'],zodiac:['rosteals','tree-rings'],'semantic-forgery':['seal','gaussian-shading-plus-plus','watermark-attacker'],
 'latent-watermark':['rosteals','lawa'],'gaussian-shannon':['gaussian-shading','prc-watermark'],gaussmarker:['tree-rings','sfwmark'],lawa:['stable-signature','latent-watermark'],'tree-rings':['ringid','gaussian-shading','sfwmark'],robin:['tree-rings','law'],ringid:['tree-rings','wind'],'object-watermark':['seal','tag-wm'],serum:['seal','watermark-attacker'],seal:['semantic-forgery','tag-wm'],sfwmark:['tree-rings','gaussmarker'],'tag-wm':['seal','serum'],'gaussian-shading':['prc-watermark','spherical-watermark','law'],t2smark:['gaussian-shading','prc-watermark'],'gaussian-shading-plus-plus':['gaussian-shading','prc-watermark'],'prc-watermark':['gaussian-shading','gaussian-shannon'],
};
const notation: Record<string,string> = {
 hidden:'x is the cover image; w is the message; E and D are the learned watermark encoder and message decoder; N is a sampled attack layer; Lmsg measures message error, Limg measures image distortion, and λimg weights distortion.',
 rosteals:'x is the cover image; EncAE and DecAE are the frozen autoencoder; w is the message; Es maps it to a learned offset; zw is the altered latent and xw the decoded marked image.',
 'stable-signature':'Enc is the frozen image encoder; Decθ is the image decoder with trainable weights θ; Dec0 is the original decoder; Extractor is fixed; w is the target signature; Ex averages over training images x; Lbits measures signature error, Limage measures output distortion, and λ weights that distortion. The minimisation variable θDec means the trainable decoder weights θ.',
 wouaf:'θ₀ are base weights; fᵤ is user u’s fingerprint; H is a learned mapping; Modulate changes weights; Gθ is the generator and zT its initial noise; θu are the modulated weights for user u, and xu is that user model’s output image.',
 aqualora:'W₀ is a base weight matrix; A and B are trainable low-rank factors; w is the watermark message; S(w) is its scaling matrix.',
 zodiac:'z is the optimised cover-image latent; F is the Fourier transform; k the watermark key; Dec the image decoder; x the cover image; Lwm measures mismatch with the key, Lperceptual measures perceptual image difference, and λp and λ₂ weight perceptual and squared pixel errors. z* is the selected minimising latent; argmin returns the latent that minimises the displayed objective.',
 ringid:'si is the similarity score for candidate key i; τ is an absolute acceptance threshold; j ranges over competing keys; margin is the minimum required score gap. The displayed decision rule is an editorial example, not the paper’s exact detector.',
 seal:'x is the candidate content; φsemantic maps it to a semantic feature vector; LSH is locality-sensitive hashing; k(x) is the resulting content-dependent watermark key.',
 sfwmark:'F(u,v) is a complex Fourier coefficient at frequency indices u and v; The overline means complex conjugation, which reverses the imaginary component. Opposite indices are taken modulo the transform dimensions.',
 'gaussian-shading':'zj is latent coordinate j; bj is its randomised bit value; N(0,1) is the standard normal distribution. Sampling is restricted to the region assigned to that bit.',
 'gaussian-shading-plus-plus':'z is the embedded initial latent, zHat its recovered estimate, n additive noise, σ² the noise variance and I the identity covariance matrix.',
};
function adapt(paper: Paper): HandbookEntry {
 const study=studyContent[paper.slug];
 const primaryId=`${paper.slug}-paper`;
 const sources: SourceRef[]=[{id:primaryId,title:paper.title,url:paper.paperUrl,basis:'primary',locator:'Primary paper linked in the original study; method description and experimental sections'},...foundationSources];
 if(paper.codeUrl) sources.push({id:`${paper.slug}-code`,title:'Linked implementation (check provenance and pinned version before reproduction)',url:paper.codeUrl,basis:'primary'});
 const sections: HandbookSection[]=[
  {id:'problem',title:'Problem and research claim',paragraphs:[paper.problem,study.thesis],sources:[primaryId]},
  {id:'mechanism',title:'Where the information enters',paragraphs:[study.intervention,study.fixedPoint,paper.boundaryDetail],bullets:paper.mechanism,sources:[primaryId]},
  {id:'recovery',title:paper.slug==='semantic-forgery'?'Attack access and observed evidence':'Recovery and access assumptions',paragraphs:[paper.detection,study.verificationAssumption],sources:[primaryId]},
  {id:'notation',title:'Notation and reading conventions',paragraphs:[notation[paper.slug] ?? 'Throughout this study, x denotes an image, z a latent representation, zT the initial noise, zt an intermediate state and z0 the clean latent. A hat denotes an estimate. m or w denotes a message, k a watermark key, θ learned parameters, and λ a loss weight. Operators and specialised quantities are explained beside each expression.','The expressions below are explanatory relationships. Read the primary method section for its exact normalisation, loss reductions and decoding conventions. A score is measured evidence, not an extracted message.'],sources:['study-guide',primaryId]},
  ...study.sections.map((s,i)=>({id:`detail-${i+1}-${sectionId(s.title)}`,title:s.title,paragraphs:[...s.paragraphs,...(s.takeaway?[s.takeaway]:[])],...(s.equation?{equation:{...s.equation,format:s.equation.format ?? 'plain' as const}}:{}),...(s.bullets?{bullets:s.bullets}:{}),sources:[primaryId]})),
  {id:'evidence',title:'Evidence and what it establishes',paragraphs:[`The linked ${paper.venue} ${paper.year} paper is the evidence source for this method. The local CPU exercise is separate teaching material and supplies no evidence of paper-scale diffusion robustness.`,study.judgement],bullets:paper.contributions,sources:[primaryId]},
  {id:'limitations',title:'Limitations and evaluation questions',paragraphs:['Evaluate these limits at a stated payload or key population, image quality, attacker access and false-positive operating point. A favourable result in one setting does not establish model-independent behaviour.'],bullets:paper.limitations,sources:[primaryId,'study-guide']},
  {id:'connections',title:'Compare the mechanism',paragraphs:study.connections,sources:[primaryId,'paper-map']},
 ];
 return {slug:paper.slug,title:paper.title,shortTitle:paper.shortTitle,kind:paper.slug==='semantic-forgery'?'Attack':'Watermark method',year:paper.year,venue:paper.venue,authors:paper.authors,family:paper.family,insertion:location[paper.slug],training:paper.boundary,summary:paper.oneLine,sections,sources,prerequisites:[{label:'Latent diffusion pipeline',to:'#/papers/ldm'},{label:'Inversion and its errors',to:'#/papers/ddim'},{label:'Evaluation mathematics',to:'#/mathematics?section=detector-threshold'}],related:related[paper.slug]??[],selfChecks:[{question:`For ${paper.shortTitle}, identify the changed object, the fixed object and the evidence available to verification.`,answer:`Changed: ${study.intervention} Fixed: ${study.fixedPoint} Verification observes: ${paper.detection} Its limiting assumption is: ${study.verificationAssumption}`},workedChecks[paper.slug] ?? {question:paper.studyQuestions[0],answer:study.judgement}],labSlug:paper.slug};
}

const S=(id:string,title:string,paragraphs:string[],sources:string[],extra:Partial<HandbookSection>={}): HandbookSection=>({id,title,paragraphs,sources,...extra});
const corePrerequisites=[{label:'Diffusion foundations',to:'#/papers/ldm'},{label:'DDIM and inversion',to:'#/papers/ddim'},{label:'Worked mathematics',to:'#/mathematics'}];
const workedChecks: Record<string,{question:string;answer:string}> = {
 'hidden':{question:'A decoder recovers bits after the training JPEG approximation but fails after saving a real JPEG. What does this show?',answer:'The training channel and real codec differ. Test the saved, reloaded JPEG at recorded quality and subsampling settings. Success through a differentiable approximation establishes only robustness to that approximation, not to the actual operation.'},
 'rosteals':{question:'The autoencoder is frozen, but the secret encoder and bit decoder are learned. Is embedding training-free?',answer:'No. Frozen image modelling saves training cost, but the message-to-latent offset and extraction still require method-specific training. Evaluate transfer to another codec separately because its latent coordinates and decoder response differ.'},
 'stable-signature':{question:'Two runs use the same denoiser and initial noise, but only one uses the fine-tuned VAE decoder. Where should the signature be expected?',answer:'The signature is rooted in the fine-tuned decoder. The ordinary decoder is a model-component replacement attack and is not expected to render that learned signature. Holding the denoiser and seed fixed does not preserve decoder-rooted evidence.'},
 'wouaf':{question:'A classifier chooses one of 100 registered users for every image, including unmarked images. Does high top-one accuracy prove attribution?',answer:'It proves only a closed-set classification result on the tested population. The detector needs a reject option and negatives from unmarked or unregistered models. Otherwise every unrelated image receives a false owner by construction.'},
 'aqualora':{question:'An unrelated LoRA is merged into a marked model and generation still looks good. What must be checked before declaring the watermark intact?',answer:'Measure extraction after the merge at the original calibrated operating point and compare useful message recovery. Good images test generative quality; they do not test whether the low-rank watermark update survived composition or cancellation.'},
 'sleepermark':{question:'A watermark survives JPEG but disappears after subject fine-tuning. Are those results contradictory?',answer:'No. JPEG changes an output image; subject fine-tuning changes the generator that produces future evidence. Persistence requires tests across fine-tuning recipes and durations, not a stronger image-processing result.'},
 'zodiac':{question:'Optimisation lowers watermark loss but changes a small word on the cover image. Is a high overall image-similarity score enough?',answer:'No. A paired-cover method promises to retain that particular image, including consequential details. Inspect semantic changes and local regions as well as global perceptual scores, and report the optimisation cost.'},
 'semantic-forgery':{question:'An unrelated image passes a target detector after optimisation. Which failure has occurred?',answer:'It is forgery or false attribution, not removal. The attacker created evidence the verifier accepts without legitimate generation. The report must state reference-image and detector-query access and whether content remained useful.'},
 'latent-watermark':{question:'Latent recovery improves on training attacks but worsens on a new resize pipeline. Which assumption failed?',answer:'The learned injection and detector did not generalise to that channel. Separate held-out image content from held-out attacks and report both. Training progress on known distortions cannot establish robustness to different processing.'},
 'gaussian-shannon':{question:'A 256-bit transmission has 99% bit accuracy. Can it safely carry an exact licence record?',answer:'Not on that evidence. With independent 1% errors, exact-message success is 0.99 to the power 256, about 7.63%. Measure complete-message recovery after the actual error-correcting decoder, including failures and coding overhead.'},
 'gaussmarker':{question:'Fusion improves marked-image scores, but the restorer also raises unmarked scores. Has detection improved?',answer:'Not necessarily. Recalibrate and evaluate the full restorer-plus-fusion detector on independent negatives. Improvement means higher true-positive performance at a comparable false-positive rate, not simply a larger watermark score.'},
 'lawa':{question:'Doubling payload keeps bit accuracy unchanged. Why might user identification worsen?',answer:'A longer identifier has more opportunities for at least one error. Under independent per-bit error p, exact recovery is (1 − p) to the message length. Compare useful payload, coding and rejection rather than assuming equal bit accuracy means equal identity reliability.'},
 'tree-rings':{question:'A Fourier pattern matches before image generation but not after save, reload and inversion. Which result counts as extraction?',answer:'Only evidence recovered from the received image counts. The pre-generation match tests construction. The failed round trip exposes generation, codec or inversion loss; substituting the stored initial noise would hide that failure.'},
 'robin':{question:'An optimiser reduces visible error by changing the marked intermediate latent itself. Does that test the advertised concealment strategy?',answer:'It changes the mechanism being tested. To isolate conditioning-based concealment, keep the intended marked state fixed and optimise the guiding conditioning. Verify exactly which tensors changed and whether the fixed watermark evidence remained intact.'},
 'ringid':{question:'Each key has a false-match probability of 0.001. Is searching 1,000 keys still a 0.001 false-positive test?',answer:'No. Under an illustrative independence assumption, at least one match occurs with probability 1 − 0.999¹⁰⁰⁰, about 63.2%. Real scores may be dependent, so calibrate the entire multi-key search rather than using the single-key threshold.'},
 'object-watermark':{question:'A prompt contains two dogs but only one should be marked. What is missing from a whole-image detection score?',answer:'It does not show which object carries the evidence. Test localisation or separate crops, including the unmarked instance and background. Object-token control must be grounded in actual image regions, not inferred from prompt wording.'},
 'serum':{question:'An image-space classifier avoids inversion and runs quickly, but flags unmarked images from the same generator. What needs investigation?',answer:'It may rely on generator artefacts rather than user-specific noise evidence. Include matched unmarked outputs and unrelated synthetic images, recalibrate open-set rejection, and test transfer across generators. Low latency does not establish attribution.'},
 'seal':{question:'A small object replacement changes the meaning but not the semantic hash. What happens to content binding?',answer:'The unchanged hash can preserve the expected watermark despite a consequential edit. The semantic encoder and hash tolerance define the binding boundary. Test small meaningful edits and adversarial collisions instead of assuming global semantic similarity implies unchanged content.'},
 'sfwmark':{question:'A Fourier coefficient is edited without its conjugate partner, then the imaginary inverse component is discarded. Was the intended pattern preserved?',answer:'Generally no. Projecting back to a real signal changes the effective Fourier coefficients. Construct conjugate pairs together and verify inverse-transform reality before evaluating recovery. Correct symmetry is necessary, but it does not make the mark immune to attacks.'},
 'tag-wm':{question:'Global ownership passes but one region is flagged as altered. Should the entire image be described as authentic?',answer:'No. Global ownership evidence and local integrity are different outputs. Report the suspected altered region and the localisation uncertainty; a persistent ownership signal cannot validate every pixel or semantic statement.'},
 'gaussian-shading':{question:'All coordinates have near-zero mean and unit variance. Is prior preservation established?',answer:'No. Correlations or higher-order dependence can remain. The randomisation and sampling construction provide the relevant theoretical conditions; finite marginal checks only test selected consequences. Evaluate key reuse and fixed-message versus random-message sampling explicitly.'},
 't2smark':{question:'A tail decoder reads the first message-length coordinates, including central samples. Is it measuring tail-embedded payload recovery?',answer:'No. Embedding and extraction must agree on the selected tail positions and ordering. Central samples should remain random rather than be counted as message bits. Test that central values are unchanged and that extraction uses the same selection rule.'},
 'gaussian-shading-plus-plus':{question:'A valid signed payload is copied into another image. Does signature verification prove that image is original?',answer:'No. The signature authenticates the signed message. It does not bind all received pixels to that message unless the protocol includes a suitable content binding and verifies it. Test transplant attacks and seed-channel failure separately.'},
 'prc-watermark':{question:'A repetition-code demonstration corrects one flipped bit. Has it demonstrated PRC computational undetectability?',answer:'No. It demonstrates a simple error-correction property. A pseudorandom-code claim needs the actual keyed construction, randomness assumptions and formal adversary model. Ordinary repetition exposes structure and must not be labelled the cryptographic result.'},
};

const newEntries: HandbookEntry[] = [
 {
 slug:'ldm',shortTitle:'Latent Diffusion',title:'High-Resolution Image Synthesis with Latent Diffusion Models',kind:'Foundation',year:'2022',venue:'CVPR',authors:'Robin Rombach, Andreas Blattmann, Dominik Lorenz, Patrick Esser and Björn Ommer',family:'Generative foundations',insertion:'No watermark',training:'Generator training',summary:'A learned image codec moves diffusion into a smaller representation while retaining an image decoder at the output.',
 sources:[{id:'ldm-paper',title:'LDM, CVPR 2022',url:'https://openaccess.thecvf.com/content/CVPR2022/html/Rombach_High-Resolution_Image_Synthesis_With_Latent_Diffusion_Models_CVPR_2022_paper.html',basis:'primary'}, {id:'ldm-code',title:'Author implementation: CompVis latent-diffusion',url:'https://github.com/CompVis/latent-diffusion',basis:'primary'},...foundationSources],prerequisites:[{label:'VAE sampling worked example',to:'#/mathematics?section=vae-sampling'}],related:['ddim','stable-signature','tree-rings'],
 sections:[
 S('problem','Why compress before diffusion?',['Denoising RGB pixels repeatedly is expensive. An autoencoder first learns a compressed representation that retains information needed for reconstruction. A separate denoising model learns the distribution of these latents. Compression reduces spatial cost but also introduces a reconstruction limit: information discarded by the encoder cannot be recovered exactly by the decoder.','The foundation paper contains no watermark. It provides the places later methods modify: the initial noise, an intermediate state, the final clean latent, the denoiser parameters or the decoder.'],['ldm-paper','paper-map']),
 S('pipeline','Follow one generated image',['Write E for the image encoder, D for the decoder, x for an image and z₀ = E(x) for a training latent. During pure text-to-image generation there is no input image to encode. Start with Gaussian noise zT, denoise using text conditioning c until z₀, then compute D(z₀).','The text encoder converts tokens to conditioning features. Cross-attention allows spatial denoising features to use that conditioning. Classifier-free guidance combines conditional and unconditional predictions at inference; its strength changes the numerical trajectory.'],['ldm-paper','study-guide'],{bullets:['Training images: x → E → z₀ → add noise → denoiser learns a prediction target.','Text-to-image: prompt → conditioning; zT → repeated denoising → z₀ → D → RGB.','Verification for a noise watermark: candidate RGB → E → approximate inversion → estimated zT → watermark test.']}),
 S('equation','What the denoiser learns',['Let ε be the sampled training noise, t a timestep, c conditioning, and εθ the denoiser with parameters θ. The squared Euclidean norm aggregates prediction errors over the latent. The expectation averages over training examples, noise and timesteps.'],['ldm-paper'],{equation:{expression:String.raw`L=\mathbb E_{z_0,\epsilon,t,c}\left[\|\epsilon-\epsilon_\theta(z_t,t,c)\|_2^2\right]`,note:'A common noise-prediction objective; other parameterisations are possible. This is not a watermark loss.',format:'latex'},workedExample:{title:'The classic 512-pixel example',steps:['A 512 × 512 RGB image contains 786,432 values.','A 4 × 64 × 64 latent contains 16,384 values, 48 times fewer scalar values.','The ratio describes tensor size, not an exact runtime speed-up. Attention, channel width, the decoder and number of denoising steps also cost computation.'],conclusion:'A watermark claiming 16,384 available coordinates is making an architecture-specific assumption.'}}),
 S('limitations','What transfers to watermark research',['A codec changes what information survives. Decoder replacement directly changes a decoder-rooted signature; a different encoder changes recovered latent evidence even when generated images remain plausible. The clean latent is not generally a collection of independent standard Gaussian coordinates. The initial noise prior is the object designed to have that simple law.','The paper studies generation and reconstruction tasks. It does not establish the security or capacity of any later watermark. Test new VAEs, latent dimensions and denoisers explicitly before transferring a watermark claim.'],['ldm-paper','study-guide']),
 ],selfChecks:[{question:'Why is the encoder absent from ordinary text-to-image generation but present in many watermark detectors?',answer:'Generation already begins in latent space, so it needs only the denoiser and final decoder. A detector receives pixels, so it must first encode them before estimating an earlier latent. This creates an additional lossy and sometimes stochastic step.'}],
 },
 {
 slug:'ddim',shortTitle:'DDIM',title:'Denoising Diffusion Implicit Models',kind:'Foundation',year:'2021',venue:'ICLR',authors:'Jiaming Song, Chenlin Meng and Stefano Ermon',family:'Sampling and inversion',insertion:'No watermark',training:'No watermark-specific training',summary:'A sampling formulation with a deterministic limit provides the trajectory used by many approximate watermark inversions.',sources:[{id:'ddim-paper',title:'Denoising Diffusion Implicit Models',url:'https://arxiv.org/abs/2010.02502',basis:'primary'},{id:'ddim-code',title:'Author implementation: ermongroup/ddim',url:'https://github.com/ermongroup/ddim',basis:'primary'},...foundationSources],prerequisites:[{label:'Latent Diffusion',to:'#/papers/ldm'}],related:['tree-rings','gaussian-shading','law'],
 sections:[S('problem','Sampling is part of verification',['A diffusion training objective need not force one stochastic sampling process. DDIM constructs a non-Markovian family with the same training objective and a deterministic sampling limit. This enables fewer sampling steps and relates latent states along a trajectory.','Watermarking uses a further operation: start from a received image, encode it and approximate the trajectory towards its noise state. The DDIM paper is a sampling foundation, not a guarantee of exact image inversion.'],['ddim-paper','paper-map']),S('mechanism','Estimate clean content, then move to another noise level',['At state zₜ the network estimates εθ, the noise component. Using the known schedule, estimate z₀. Combine that estimate with a direction towards the next timestep. With stochasticity set to zero, fixed initial noise, model, schedule and conditioning produce a deterministic trajectory.','For inversion, the required prediction at the unknown next state is unavailable. Practical routines reuse or approximate predictions. Quantisation and image encoding prevent a perfect RGB round trip even if numerical latent steps were exact.'],['ddim-paper','study-guide']),S('equation','The clean-latent estimate',['Here ᾱₜ is cumulative signal retention, zₜ the observed latent, εθ the network noise prediction at timestep t and conditioning c, and ẑ₀ the estimated clean latent.'],['ddim-paper'],{equation:{expression:String.raw`\hat z_0=\frac{z_t-\sqrt{1-\bar\alpha_t}\,\epsilon_\theta(z_t,t,c)}{\sqrt{\bar\alpha_t}}`,note:'Prediction error is multiplied by √((1 − ᾱₜ)/ᾱₜ). Small ᾱₜ can amplify it.',format:'latex'},workedExample:{title:'An inversion error budget',steps:['With ᾱₜ = 0.64, the multiplier is 0.6/0.8 = 0.75.','A +0.2 noise-prediction error gives a −0.15 error in the clean-latent estimate.','With ᾱₜ = 0.01 the multiplier is approximately 9.95, making the same error about −1.99.'],conclusion:'The calculation is local and scalar. It explains sensitivity, not total multi-step image inversion error.'}}),S('evidence','A controlled inversion experiment',['Generate and store the true initial noise only as ground truth. Save the RGB output, reload it, encode it and invert without giving the detector the ground-truth noise. Measure latent error, watermark score and recovery separately.','Vary steps, scheduler, prompt availability, guidance and VAE one at a time. A score change then has an interpretable source. Determinism does not remove these mismatches.'],['study-guide','paper-map']),S('limitations','The detector inherits the inverse',['A low image reconstruction error is not equivalent to accurate initial-noise recovery. Several noise states may produce similar visible content. A watermark detector cares about particular coordinates or frequency structure, which a perceptual reconstruction metric can ignore.','A method requiring matched DDIM settings has an access assumption. State that assumption when comparing it with a direct pixel decoder.'],['paper-map','study-guide'])],selfChecks:[{question:'Can a deterministic sampler guarantee exact watermark extraction?',answer:'No. Determinism fixes the forward result for given inputs. Extraction must estimate hidden states from lossy pixels, often with an approximate reverse trajectory and unavailable conditioning. Those are different requirements.'}],
 },
];
newEntries.push(
 {
 slug:'wind',shortTitle:'WIND',title:'Hidden in the Noise: Two-Stage Robust Watermarking for Images',kind:'Watermark method',year:'2025',venue:'ICLR',authors:'Kasra Arabi, Benjamin Feuer, R. Teal Witter, Chinmay Hegde and Niv Cohen',family:'Initial-noise identity',insertion:'Initial noise: identity and Fourier group',training:'No method-specific training',summary:'Use the initial random noise as an identity, then add a group signal to make searching for that identity practical.',sources:[{id:'wind-paper',title:'Hidden in the Noise',url:'https://arxiv.org/abs/2412.04653',basis:'primary'},{id:'wind-code',title:'Author implementation: Hidden-in-the-Noise',url:'https://github.com/Kasraarabi/Hidden-in-the-Noise',basis:'primary'},...foundationSources],prerequisites:corePrerequisites,related:['ringid','tree-rings','gaussian-shading'],
 sections:[S('problem','Identity already exists in a noise sample',['A generated image starts from a high-dimensional random sample. If inversion recovers enough of it, that sample can identify the generation event without first overwriting it with a payload. The immediate obstacle is lookup: an owner with many historical samples cannot cheaply compare every candidate against every stored noise.','Separate the distortion-free initial-noise identity argument from the complete WIND system. The latter adds a group pattern for efficient retrieval. The existence of a naturally random identity does not by itself prove that every added group signal preserves the full distribution.'],['wind-paper','quick-reference']),S('mechanism','A coarse search followed by a specific match',['Partition the registered noise identities into groups. Add a Fourier group identifier to the selected starting noise and generate with the fixed diffusion model. Preserve enough state to reconstruct or retrieve the registered noise identities.','At verification, invert the received image. First recover a likely group from its group signal. Then compare the recovered noise with identities inside that group. A positive group result alone is not proof of the final identity.'],['wind-paper','quick-reference'],{bullets:['The generator weights stay fixed. The group-augmented initial noise changes.','Verification needs inversion, group patterns and registered identity state.','An incorrect first-stage group can prevent the true identity reaching the second stage.']}),S('equation','Search cost is part of the method',['Let N be the registered identity count, G the number of equal-size groups, and d the cost of comparing two noise vectors. A simplified linear scan over group keys and then one group has cost proportional to d(G + N/G). This is an explanatory operation count, not a runtime model from the paper.'],['study-guide','wind-paper'],{equation:{expression:String.raw`C_{\mathrm{two\ stage}}\propto d\left(G+\frac NG\right),\qquad C_{\mathrm{full}}\propto dN`,note:'It assumes balanced groups, one selected group and linear comparisons. Inversion, database access and fallback search add costs.',format:'latex'},workedExample:{title:'A million identities',steps:['With N = 1,000,000 and G = 1,000, one group contains 1,000 identities.','The simplified count is 1,000 group comparisons plus 1,000 identity comparisons rather than one million.','If the first stage fails, this saving does not establish correct attribution. Measure group recall as well as final identification and latency.'],conclusion:'Efficient retrieval is only useful when the correct identity survives candidate selection.'}}),S('evidence','What to measure',['The paper evaluates robustness and efficient detection; its author repository includes search-time experiments. Reproduce latency as the database grows and count storage, inversion and lookup separately.','Measure open-set rejection on unregistered images, false attribution as the enrolled population grows, and accuracy under transformations that damage the group signal differently from the full noise identity.'],['wind-paper','wind-code']),S('limitations','State and forgery remain security questions',['Stored identity state can be lost, leaked or inconsistently indexed. A group identifier reduces search cost but adds an attack target. Neither database membership nor a matching signal alone establishes that all image content is authentic.','Compared with RingID, distinguish group retrieval from directly assigning an identity to a Fourier key. Compared with Gaussian Shading, distinguish identity lookup from extracting a general bit message.'],['quick-reference','study-guide'])],selfChecks:[{question:'The true noise matches strongly, but the retrieved group is wrong. Should the detector identify the image?',answer:'Not from the advertised two-stage result. The matching identity was never compared. Record a first-stage retrieval failure, or explicitly run and report a fallback search with its extra cost. Counting the inaccessible ground-truth match would overstate system accuracy.'}],
 },
 {
 slug:'spherical-watermark',shortTitle:'Spherical Watermark',title:'Spherical Watermark: Encryption-Free, Lossless Watermarking for Diffusion Models',kind:'Watermark method',year:'2026',venue:'ICLR',authors:'Xiaoxiao Hu, Jiaqi Jin, Sheng Li, Wanli Peng, Xinpeng Zhang and Zhenxing Qian',family:'Gaussian prior geometry',insertion:'Initial noise: direction and radius',training:'No method-specific training',summary:'Combine message bits and random padding with spherical geometry to construct message-bearing initial noise.',sources:[{id:'spherical-paper',title:'Spherical Watermark, ICLR 2026',url:'https://proceedings.iclr.cc/paper_files/paper/2026/hash/bb97e9a7c811904c9b01f51fde66edcf-Abstract-Conference.html',basis:'primary'},...foundationSources],prerequisites:corePrerequisites,related:['gaussian-shading','law','prc-watermark'],
 sections:[S('problem','Separate payload from Gaussian geometry',['Initial-noise methods need both readable structure and a suitable generator prior. This work replaces per-image encryption machinery with a geometric construction involving message repetition, random padding, a direction mapping and an orthogonal transformation.','Encryption-free does not mean key-free or unforgeable. Ask what transformation is secret and what an adversary learns across repeated messages. A distributional construction and a security proof establish different properties.'],['spherical-paper','quick-reference']),S('mechanism','Build direction, then supply radial scale',['Mix repeated message bits with random padding. Map the resulting code to a direction, apply an orthogonal rotation and combine it with the required radial distribution. Feed the resulting noise to the unchanged generator.','After image inversion, undo the known transformation, interpret the direction in the corresponding code representation and aggregate repeated bit evidence. The exact mapping and decision boundaries belong to the primary algorithm; an arbitrary normalised bit vector is not a reproduction.'],['spherical-paper','quick-reference']),S('equation','The Gaussian decomposition has two requirements',['Let u be uniform on the unit sphere in d dimensions and R an independent non-negative radius. If R² follows a chi-squared distribution with d degrees of freedom, then z = Ru is standard multivariate Gaussian. Q is orthogonal when QᵀQ = I and preserves vector length.','The exact Gaussian identity below is a mathematical reference condition. It does not prove that every finite message-to-direction code has a uniform direction, or that fixed-message samples are independent. The paper states a proof through third-order moments and empirical distribution tests; do not replace those with a stronger unconditional independence claim.'],['spherical-paper','study-guide'],{equation:{expression:String.raw`z=Ru,\quad R^2\sim\chi_d^2,\quad u\sim\mathrm{Unif}(S^{d-1}),\quad R\perp u,\quad Q^TQ=I`,note:'R follows a chi distribution; R squared follows chi-squared. Orthogonal rotation alone cannot turn a non-uniform direction distribution into a uniform one.',format:'latex'},workedExample:{title:'Why radius alone is insufficient',steps:['In two dimensions, choose directions only from the four coordinate axes and draw the correct Gaussian radius.','Rotating all four directions preserves four discrete directions. The resulting distribution cannot be a continuous two-dimensional Gaussian.','Random padding and the actual mapping must therefore be examined, rather than relying only on a radius histogram.'],conclusion:'Matching a radial distribution and low-order moments does not establish the entire joint law.'}}),S('evidence','Read “lossless” as a qualified distribution claim',['The ICLR publication reports moment analysis and statistical tests alongside image experiments. The supplied paper map calls for marginal, covariance and radial checks before a full diffusion experiment. No numerical ranking is repeated here because quality and attack conditions must accompany such a comparison.','Separate the theorem, the tested statistical distinguishers and the downstream image-quality measurements. None is a substitute for adaptive forgery evaluation.'],['spherical-paper','paper-map']),S('limitations','What can fail after inversion',['Directional error can cross decoding boundaries, and repetitions can fail together under correlated perturbations. Test useful payload after accounting for padding and repetition.','Compare storage and verification access against Gaussian Shading and LAW-M, and compare the formal adversary against PRC. Their different objectives prevent a single “preserves Gaussianity” label from establishing equivalent security.'],['quick-reference','study-guide'])],selfChecks:[{question:'A latent passes mean, covariance and radius tests. Is it proven to be an independent Gaussian sample?',answer:'No. Those checks constrain only selected properties. Higher-order or conditional dependence can remain. State the proven property and the tested alternatives separately, then test samples for fixed and varied messages and keys.'}],
 },
 {
 slug:'law',shortTitle:'LAW / LAW-M',title:'Correlation-Aware and Gaussianity-Preserving Robust Latent Angular Watermarking for Diffusion Models',kind:'Watermark method',year:'2026',venue:'arXiv preprint; NeurIPS status unverified',authors:'Yebin Zheng, Haonan An, Guang Hua, Zhiping Lin and Yuguang Fang',family:'Angular initial-noise mapping',insertion:'Initial noise: paired relative angles',training:'No method-specific training',summary:'Encode bits through relative angles while exposing the induced dependence; LAW-M selects larger pairs and requires per-image ordering state.',sources:[{id:'law-paper',title:'LAW / LAW-M preprint, sections 3 to 4',url:'https://arxiv.org/html/2607.22386v1',basis:'primary'},...foundationSources],prerequisites:corePrerequisites,related:['gaussian-shading','spherical-watermark','t2smark'],
 sections:[S('problem','Marginals and independence are different claims',['A Gaussian-looking histogram can hide dependence between coordinates. LAW makes this explicit by deriving the correlations induced by pairing latent values. The design seeks stable angular evidence while retaining Gaussian marginal behaviour; it does not claim to leave the full independent prior unchanged.','The supplied documents call this a NeurIPS 2026 manuscript. A public arXiv preprint is available, but conference acceptance is not established here. LAW is distinct from the existing LAWA decoder-based paper.'],['law-paper','quick-reference']),S('mechanism','Use reference pairs to define an angle',['Flatten initial noise and form disjoint two-coordinate vectors. Split them into encoding pairs xᵢ, reference pairs rᵢ and unused coordinates. For bit mᵢ, rotate xᵢ to ±π/2 relative to rᵢ while keeping its radius ρᵢ. References and unused coordinates remain fixed. Diffusion weights are unchanged.','LAW repeats bit evidence and combines estimates after inversion. LAW-M sorts pairs by magnitude before choosing encoding and reference regions, embeds once in its reported configuration and stores the original pair indices as an image-specific private key. Sorting the attacked latent again is not equivalent to restoring this original order.'],['law-paper','quick-reference']),S('equation','Angular separation and local stability',['Let φr,i be the angle of reference pair rᵢ, mᵢ a binary message bit and ρᵢ the preserved norm of encoding pair xᵢ. Let σ² be the variance of a small isotropic perturbation to a pair. The angular variance approximation requires σ much smaller than ρᵢ.'],['law-paper'],{equation:{expression:String.raw`\phi'_{x,i}=\phi_{r,i}+(1-2m_i)\frac\pi2,\quad x'_i=\rho_i(\cos\phi'_{x,i},\sin\phi'_{x,i}),\quad\mathrm{Var}(\Delta\phi)\approx\frac{\sigma^2}{\rho_i^2}`,note:'The two bit targets differ by π. The variance expression is a local approximation for one pair, not a complete decoded-message error bound.',format:'latex'},workedExample:{visual:'angular-variance',title:'Magnitude matters without changing the angular code',steps:['With σ = 0.1 and ρ = 1, the local angular variance is approximately 0.01 radians squared.','With the same perturbation scale and ρ = 2, it is approximately 0.0025, one quarter as large.','The improvement does not remove reference-pair error, inversion dependence or the need to restore LAW-M’s saved ordering.'],conclusion:'Larger pair norms can stabilise angular estimates, with storage and dependence still part of the method.'}}),S('recovery','Invert, restore ordering and interpret relative angles',['DDIM inversion supplies estimated pairs. Restore the original layout, use the saved ordering for LAW-M, and estimate bit values from relative phase; combine repeated estimates for LAW. Wrong ordering compares unrelated pairs and destroys the message relation.','Implementation caution: atan2 angles wrap at ±π. The preprint writes a direct comparison of absolute angles in its decoding equation. A circular implementation must reconcile this with the stated relative-angle construction. Test reference angles on both sides of the branch cut rather than silently claiming the printed comparison is universally valid.'],['law-paper']),S('evidence','Reported setting and the scope of the claim',['The primary preprint reports Stable Diffusion 2.1, 50-step DPM-Solver++ generation, 50-step DDIM inversion and empty-prompt verification. Its image-quality and attack results are tied to those conditions. The supplied summary records repetition for LAW and per-image ordering for LAW-M.','Structured off-diagonal covariance remains even when individual coordinates retain suitable marginals. Limited classifier failures to distinguish marked samples are empirical tests, not computational indistinguishability theorems.'],['law-paper','quick-reference']),S('limitations','The cost changes between variants',['Repetition spends coordinates and adds dependence. Magnitude selection can reduce angular sensitivity but requires per-image state. Losing that state or recomputing order after corruption changes the decoding problem.','Evaluate angular errors, covariance, complete-message recovery and key-management failure separately. Generalisation beyond the tested generator and inversion settings requires new evidence.'],['law-paper','study-guide'])],selfChecks:[{question:'Why can LAW preserve each coordinate’s marginal law yet reveal a watermark through joint statistics?',answer:'Encoding couples an encoding pair’s angle to a reference pair. Each angle can remain marginally uniform while the relative angle is fixed by a bit. Observing pairs jointly exposes that relation. Independence is a property of the joint distribution, not of separate histograms.'}],
 }
);
newEntries.push(
 {
 slug:'watermark-attacker',shortTitle:'WatermarkAttacker',title:'Invisible Image Watermarks Are Provably Removable Using Generative AI',kind:'Attack',year:'2024',venue:'NeurIPS',authors:'Xuandong Zhao, Kexun Zhang, Zihao Su, Saastha Vasan, Ilya Grishchenko, Christopher Kruegel, Giovanni Vigna, Yu-Xiang Wang and Lei Li',family:'Regeneration attacks',insertion:'No embedding: attacks received pixels',training:'Uses a pre-trained regeneration model',summary:'Destroy fragile evidence through noise or compression, then reconstruct useful image content with a generative model.',sources:[{id:'attacker-paper',title:'WatermarkAttacker, NeurIPS 2024',url:'https://proceedings.neurips.cc/paper_files/paper/2024/hash/10272bfd0371ef960ec557ed6c866058-Abstract-Conference.html',basis:'primary'},{id:'attacker-code',title:'Author implementation: WatermarkAttacker',url:'https://github.com/XuandongZhao/WatermarkAttacker',basis:'primary'},...foundationSources],prerequisites:corePrerequisites,related:['waves','semantic-forgery','serum'],
 sections:[S('problem','Removal without destroying the image',['A watermark can survive ordinary JPEG or resize and still be lost when another model reconstructs the image. This attack targets the gap between preserving semantic content and preserving fine image details. It starts from a received watermarked image, not from the original generation noise.','The theorem has assumptions and concerns a class of invisible watermarks. The title must not be read as proof that every watermark under every threat model is removable at zero quality cost.'],['attacker-paper','quick-reference']),S('mechanism','Destroy and reconstruct',['A regeneration attack corrupts an image or its encoded representation, then applies a denoising or generative reconstruction model. The destructive step reduces watermark information; the reconstruction step restores plausible visual content. The author implementation includes diffusion and VAE variants.','State whether the attacker needs the watermark detector, model weights, a reference image or queries. A regeneration model can be separate from the protected generator, but transfer across every model is not automatic.'],['attacker-paper','attacker-code']),S('equation','Measure the two competing outcomes',['Let Aη be an attack with strength η, x the marked input, s the verifier score and Q a distortion measure between input and attacked output. A removal objective minimises detection evidence subject to a quality budget δ. This is an evaluation formulation, not the paper’s theorem.'],['study-guide','attacker-paper'],{equation:{expression:String.raw`\min_\eta s(A_\eta(x))\quad\mathrm{subject\ to}\quad Q(x,A_\eta(x))\le\delta`,note:'Lower scores are assumed to mean less evidence. Use the actual detector direction and include semantic checks where the quality metric is insufficient.',format:'latex'},workedExample:{title:'An attack curve beats one success count',steps:['Suppose a mild attack leaves TPR at 80% with little visual change. A stronger attack lowers TPR to 20% but changes object details.','Report both operating points at the same verifier threshold, alongside distortion and semantic preservation.','Do not retune the detector on each attacked test set or label a destroyed image as useful removal success.'],conclusion:'Removal is only meaningful together with an acceptable content and quality constraint.'}}),S('evidence','What a reproduction would establish',['The primary work combines formal analysis with experiments on invisible watermark schemes. These results motivate regeneration as an evaluation family. They do not establish that the same numerical success rate transfers to new methods, checkpoints or attack budgets.','Compare against simple noise and compression at matched quality to isolate the benefit of reconstruction. Include genuine unmarked negatives to ensure the detector’s operating point remains known.'],['attacker-paper','study-guide']),S('limitations','Removal is not forgery',['Suppressed detection does not create evidence for another owner. Conversely, an attack that transplants a valid signal is an attribution failure even if the signal itself is hard to remove. Evaluate both when claiming provenance security.','A semantic watermark may respond differently because its evidence is tied to content that regeneration preserves. That possibility requires a defined semantic validity boundary, not the assumption that more persistence is always better.'],['attacker-paper','study-guide'])],selfChecks:[{question:'A regeneration attack removes 99% of marks but replaces the subject. Has it established a useful attack?',answer:'Only under a threat model that permits that content change. For content-preserving removal, it violates the constraint. Report the failure rate with the actual distortion and semantic changes instead of treating the removal percentage as sufficient.'}],
 },
 {
 slug:'waves',shortTitle:'WAVES',title:'WAVES: Benchmarking the Robustness of Image Watermarks',kind:'Benchmark',year:'2024',venue:'ICML',authors:'Bang An and colleagues',family:'Attack and evaluation benchmark',insertion:'No watermark',training:'Depends on the evaluated method',summary:'Evaluate detection and identification across attack families while recording the quality cost of removal.',sources:[{id:'waves-paper',title:'WAVES, ICML 2024',url:'https://proceedings.mlr.press/v235/an24a.html',basis:'primary'},{id:'waves-code',title:'Author implementation: WAVES',url:'https://github.com/umd-huang-lab/WAVES',basis:'primary'},...foundationSources],prerequisites:[{label:'Detection thresholds',to:'#/mathematics?section=detector-threshold'},{label:'Regeneration attacks',to:'#/papers/watermark-attacker'}],related:['markdiffusion','watermark-attacker','ringid'],
 sections:[S('problem','A short attack table can hide a weak claim',['A method can appear robust if testing selects only convenient transforms, strengths or detector thresholds. WAVES brings conventional image processing, diffusion-based attacks and adversarial attacks into a common evaluation setting. It evaluates detection and identification together with image quality.','The benchmark does not embed one universal watermark. Its objects of comparison are existing methods and attack configurations.'],['waves-paper','quick-reference']),S('protocol','Specify a comparison before running it',['Fix payload or identity population, generator settings, candidate image distribution and detector calibration. Sweep attack strength while preserving the original operating point. Log both detector output and image-quality measurements for each sample.','Use separate calibration and test data. In identification, include rejection of unregistered images instead of always returning the closest owner. Record the attacker’s model, query and reference-image access.'],['waves-paper','study-guide'],{bullets:['Traditional processing tests a known transformation family.','Regeneration tests a second model replacing fine details.','Adaptive attacks target the actual defence or a stated surrogate.','A quality measure must match the task: paired fidelity and distributional realism answer different questions.']}),S('equation','Compare a curve, not an isolated rate',['Let τ be fixed using unmarked calibration data to target FPR α. For attack strength η, measure TPRη and distortion Qη on the same held-out marked population. The pair (Qη, TPRη) shows how much quality the attacker spends to suppress detection.'],['study-guide'],{equation:{expression:String.raw`\mathrm{TPR}_\eta=P(s(A_\eta(X_{\mathrm{marked}}))>\tau),\qquad P(s(X_{\mathrm{unmarked}})>\tau)\approx\alpha`,note:'The approximation reflects finite calibration data. Specify whether FPR is evaluated on pristine or attacked unmarked samples, and report both if deployment contains both.',format:'latex'},workedExample:{title:'An unfair ranking',steps:['Method A carries 256 useful bits; method B detects only presence. A reports BER after JPEG and B reports TPR at an unspecified threshold.','Those values measure different outcomes and cannot establish that B is more robust.','Match the decision task, useful payload, attack quality and FPR before comparing. If matching is impossible, report distinct tasks rather than a single ranking.'],conclusion:'Benchmark software standardises execution, while the experiment designer still controls fairness.'}}),S('evidence','Keep the conditions attached to the result',['The paper and repository define the benchmark attacks and protocol. Pin versions because decoder wrappers, attack defaults and image pre-processing can affect scores. Reproduce one known result before extending the suite.','Report uncertainty and sample counts, including failures and rejected inputs. A low observed FPR from a small negative set has limited statistical precision.'],['waves-paper','waves-code','study-guide']),S('limitations','A benchmark is a starting threat model',['A fixed attack suite cannot cover all future adaptive strategies. Test methods against attacks informed by their specific structure, not only against an unchanged menu.','Averaging over attacks can hide a severe failure in one family. Report per-attack behaviour and quality curves alongside any aggregate.'],['quick-reference','study-guide'])],selfChecks:[{question:'Two methods have the same TPR after an attack. What else is needed to compare them?',answer:'At least the FPR and calibration data, payload or identity count, image quality after attack, attack access and budget, generator settings and runtime. Equal TPR at different false-positive rates or quality costs is not equal robustness.'}],
 },
 {
 slug:'markdiffusion',shortTitle:'MarkDiffusion',title:'MarkDiffusion: An Open-Source Toolkit for Generative Watermarking of Latent Diffusion Models',kind:'Benchmark',year:'2026',venue:'JMLR 27(204)',authors:'Leyi Pan and colleagues',family:'Implementation and evaluation toolkit',insertion:'No single embedding location',training:'Depends on the selected algorithm',summary:'A shared implementation and evaluation interface reduces repeated engineering while keeping method fidelity an explicit responsibility.',sources:[{id:'markdiffusion-paper',title:'MarkDiffusion, JMLR 2026',url:'https://www.jmlr.org/beta/papers/v27/25-2553.html',basis:'primary'},{id:'markdiffusion-code',title:'Author toolkit: THU-BPM/MarkDiffusion',url:'https://github.com/THU-BPM/MarkDiffusion',basis:'primary'},...foundationSources],prerequisites:[{label:'WAVES and fair evaluation',to:'#/papers/waves'},{label:'Latent diffusion',to:'#/papers/ldm'}],related:['waves','tree-rings','gaussmarker'],
 sections:[S('problem','Common interfaces remove only some differences',['Watermark repositories often duplicate generation, inversion, image attacks and metrics with incompatible defaults. MarkDiffusion provides a shared framework, visualisation and evaluation tools. It is an experimental toolkit, not a new bit-embedding construction.','The JMLR record confirms publication in 2026. Feature counts and supported algorithms are version-dependent, so this handbook does not treat a moving repository list as a fixed scientific result.'],['markdiffusion-paper','paper-map']),S('workflow','Establish implementation parity before comparison',['Select a method and pin the toolkit commit, model checkpoint and dependencies. Run the original author implementation and toolkit implementation on matched prompts, seeds, payloads and attack parameters. Compare embedded evidence, recovery scores and decisions, not just final image appearance.','The relevant differences include latent scaling, scheduler steps, classifier-free guidance, VAE encoding mode, Fourier conventions and detector thresholds. A common wrapper can preserve these differences or accidentally replace them.'],['markdiffusion-paper','study-guide'],{bullets:['A wrapper calls original code; a reimplementation reproduces a specification. Record which one is used.','Save configuration, key policy, intermediate diagnostic values and output paths with each run.','Separate successful execution from matching the original algorithm and matching the paper’s reported experiment.']}),S('worked-example','An apparent regression can be a configuration mismatch',['Suppose a direct author run detects its own output, while a toolkit run misses an image generated from the same seed. The seed alone does not guarantee a matched experiment.'],['study-guide'],{workedExample:{title:'Investigate one variable at a time',steps:['Compare model and VAE hashes, latent scaling, image decoding and precision.','Compare sampler, step indices, conditioning and guidance during both generation and inversion.','Compare the recovered signal before thresholding. If signals match but decisions differ, inspect threshold direction, normalisation and calibration.'],conclusion:'A systematic parity check identifies implementation differences before attributing the result to a scientific limitation.'}}),S('evidence','What the toolkit does and does not prove',['The publication describes the implementation, visualisation and evaluation framework. Using it improves repeatability only when versions and settings are recorded. It cannot make an unmatched payload comparison fair or turn a toy operation into a paper reproduction.','Use a small command test to validate file flow. Use a separate matched experiment for algorithm parity and a suitably sized evaluation for robustness claims.'],['markdiffusion-paper','study-guide']),S('limitations','Shared code can create shared errors',['A defect in a shared inversion or attack component can affect several methods together and make results look consistent. Validate representative outputs against independent implementations.','The toolkit is a useful starting point for the reproduction sequence in the paper map: one initial-noise method, one model-integrated method, then attacks and benchmarks. Hardware-heavy experiments remain outside this site’s CPU teaching demonstrations.'],['paper-map','study-guide'])],selfChecks:[{question:'Does using a unified API make two watermark results directly comparable?',answer:'No. The API can hide different payloads, training, inversion assumptions, thresholds and model settings. Compare the configurations and validate one original implementation before treating a shared interface as evidence of parity.'}],
 },
 {
 slug:'push-it-away',shortTitle:'Push It Away',title:'Push It Away: Repulsive Non-Watermark Representation for Box-Free Model Watermarking',kind:'Watermark method',year:'2026',venue:'WIFS manuscript described in supplied summary; status unverified',authors:'Not independently verified from the manuscript',family:'Output-space detector training',insertion:'RGB model output',training:'Auxiliary training',summary:'Change the non-watermark training target so clean extractor responses are separated from the watermark, rather than accidentally correlated with it.',sources:[{id:'push-summary',title:'Supplied updated quick reference: Push It Away',basis:'supplied-summary',locator:'LDW_Paper_Quick_Reference_Updated.docx, paragraphs 480 to 496 (zero-based)'},...foundationSources],prerequisites:[{label:'HiDDeN',to:'#/papers/hidden'},{label:'Thresholds',to:'#/mathematics?section=detector-threshold'}],related:['hidden','semantic-forgery','waves'],
 sections:[S('source-status','Source status and scope',['This entry is based on the supplied updated summary and paper map. The underlying WIFS 2026 manuscript was not supplied as a separate file and no matching public primary source was located during this review. Its equations, implementation and reported numerical results have not been independently verified.','The paper concerns a box-free output-watermarking framework. It does not propose an initial-noise, intermediate-latent or clean-latent insertion rule. The change is to training targets and losses within an existing hiding-network and extractor system.'],['push-summary']),S('problem','A negative target can resemble the positive watermark',['A fixed all-white non-watermark target may correlate with a logo watermark under an uncentred normalised correlation score. If clean outputs are already close to the positive score, a detector needs a threshold near the positive class and has little tolerance for perturbation.','The supplied summary describes replacing that fixed negative target with a representation trained away from the watermark. Margin-based repulsion can stop after enough separation; reciprocal-distance repulsion continues with decreasing influence. These are the reported design ideas, not a reproduced loss implementation.'],['push-summary']),S('mechanism','Change the negative class while retaining the architecture',['The hiding network H embeds a fixed image or logo watermark in model output; the extraction decoder D reads it from a received image Z. Their joint training continues to encourage marked outputs to recover the watermark W, while clean outputs are pushed away from W.','The supplied summary says the method changes the negative target or loss rather than network architecture and is compatible with Decoder Gradient Shield. It is not presented as a general multi-bit message channel.'],['push-summary']),S('equation','Why centring changes correlation',['For a vector a of extracted values and reference watermark b, the expression below is centred normalised correlation. The means ā and b̄ remove constant brightness. Both centred vectors must have non-zero norm. This is an explanatory definition, not a verified transcription of the unavailable manuscript.'],['push-summary','study-guide'],{equation:{expression:String.raw`\mathrm{NC}(a,b)=\frac{(a-\bar a\mathbf1)^T(b-\bar b\mathbf1)}{\|a-\bar a\mathbf1\|_2\,\|b-\bar b\mathbf1\|_2}`,note:'A constant all-white vector has zero centred norm, so this score is undefined for it. A real detector must specify its handling of zero-variance outputs.',format:'latex'},workedExample:{title:'Brightness can create a misleading raw score',steps:['Take logo vector b = [1, 1, 0, 0] and white negative a = [1, 1, 1, 1].','Their uncentred cosine similarity is 2/(2 × √2) ≈ 0.707, despite the negative not representing the logo.','Centring makes the white vector zero. It cannot simply be passed to a normalised score without a defined zero-variance rule. Repulsive learning and score choice therefore need joint validation.'],conclusion:'Changing a threshold alone cannot repair a poorly defined negative score distribution.'}}),S('evidence','Read reported results as supplied-summary claims',['The summary reports separation of clean and watermarked responses and improved robustness under selected noise and quantisation conditions. This handbook does not repeat its success rates or threshold recommendations as independently established results.','A concrete validation would save positive and negative score distributions across logos, content categories and transformations, then choose a threshold on separate calibration data. A visually wider margin is insufficient without false-positive and false-negative measurements.'],['push-summary','study-guide']),S('limitations','Better separation is not complete security',['The supplied summary leaves query-based removal and learned adaptive negative targets for future work. Robustness to particular transforms cannot establish resistance to a detector-aware attacker.','A fixed logo signal can still be copied or imitated. The method addresses detector separation; content binding, ownership evidence and forgery need their own assumptions and experiments.'],['push-summary','study-guide'])],selfChecks:[{question:'Why should a threshold near 0.5 from one experiment not become a universal detector setting?',answer:'The score depends on centring, output variance, logo structure and the training data. Its distributions can shift under new content and attacks. Select and test the threshold using the actual deployment negatives and positives, and define the score for degenerate outputs first.'}],
 }
);

export const handbookEntries: HandbookEntry[] = [
 ...newEntries.filter(entry=>entry.kind==='Foundation'),
 ...[...papers,...additionalPapers].map(adapt),
 ...newEntries.filter(entry=>entry.kind!=='Foundation'),
].map(entry=>({...entry, prerequisites:entry.prerequisites.map(item=>({...item,to:item.to.replace(/^#/, '')}))}));
export const handbookBySlug = new Map(handbookEntries.map(entry=>[entry.slug,entry]));

// Section-level claim register is generated from the rendered records, avoiding a stale second catalogue.
export const claimSourceRegister = handbookEntries.flatMap(entry => entry.sections.map(section => ({
  id: `${entry.slug}:${section.id}`,
  route: `#/papers/${entry.slug}?section=${section.id}`,
  claims: [...section.paragraphs, ...(section.bullets ?? [])],
  equation: section.equation,
  workedExample: section.workedExample,
  sources: section.sources.map(id => entry.sources.find(source => source.id === id)!),
  interpretation: section.workedExample ? 'Worked examples are editorial teaching calculations, not reported paper experiments.' : 'Mechanism descriptions follow cited sources; evaluation questions and failure scenarios are editorial analysis.',
})));
